import sys

def find_exploding_player(K, N, questions):
    current_player = K - 1
    total_time = 0

    for time, result in questions:
        total_time += time
        if total_time >= 210:
            break
        if result == 'T':
            current_player = (current_player + 1) % 8
            if current_player == 0:
                current_player = 7

    return current_player + 1

if __name__ == "__main__":
    K = int(sys.stdin.readline().strip())
    N = int(sys.stdin.readline().strip())
    questions = [tuple(map(int, sys.stdin.readline().strip().split())) for _ in range(N)]

    result = find_exploding_player(K, N, questions)
    print(result)
